const finalRows = $("Lay Final Decisions").all().map(i => i.json);
const riskRows = $("Lay Risk Assessments").all().map(i => i.json);

const riskBySymbol = {};
for (const r of riskRows) riskBySymbol[r.symbol] = r;

const results = [];

for (const f of finalRows) {
  const risk = riskBySymbol[f.symbol] || null;

  const originalSignal = (f.final_signal || "HOLD").toUpperCase();
  const originalConfidence = f.final_confidence !== null && f.final_confidence !== undefined
    ? parseFloat(f.final_confidence) : null;

  let adjustedSignal = originalSignal;
  let adjustedConfidence = originalConfidence;
  let positionSize = 100;
  const reasons = [];

  if (!risk) {
    reasons.push("Chua co danh gia Risk AI cho coin nay - giu nguyen tin hieu goc, giam position size de an toan");
    positionSize = 50;
  } else {
    const riskLevel = risk.risk_level;
    const atrRegime = risk.atr_regime;

    if (riskLevel === "HIGH") {
      adjustedSignal = "HOLD";
      adjustedConfidence = originalConfidence !== null ? Math.round(originalConfidence * 0.3) : null;
      positionSize = 0;
      reasons.push(`Risk AI danh gia HIGH risk (score ${risk.risk_score}) - tam hoan giao dich du tin hieu goc la ${originalSignal}`);
    } else if (riskLevel === "MEDIUM") {
      adjustedConfidence = originalConfidence !== null ? Math.round(originalConfidence * 0.7) : null;
      positionSize = 50;
      reasons.push(`Risk AI danh gia MEDIUM risk (score ${risk.risk_score}) - giam confidence va position size xuong 50%`);
    } else {
      reasons.push(`Risk AI danh gia LOW risk (score ${risk.risk_score}) - giu nguyen tin hieu va full position size`);
    }

    if (atrRegime === "tang_cao" && positionSize > 0) {
      positionSize = Math.max(0, positionSize - 20);
      reasons.push("ATR dang tang cao bat thuong - giam them 20% position size de phong ngua bien dong dot bien");
    }
  }

  results.push({
    json: {
      symbol: f.symbol,
      original_signal: originalSignal,
      original_confidence: originalConfidence,
      risk_level: risk ? risk.risk_level : null,
      risk_score: risk ? risk.risk_score : null,
      atr_regime: risk ? risk.atr_regime : null,
      adjusted_signal: adjustedSignal,
      adjusted_confidence: adjustedConfidence,
      position_size_pct: positionSize,
      reason: reasons.join("; ")
    }
  });
}

return results;
